        try:
            with zipfile.ZipFile(zip_path, 'r') as zip_ref:
                zip_ref.extractall(ZIP_DIR)

            # Get list of extracted filenames
            extracted_files = []
            for item in ZIP_DIR.iterdir():
                if item.is_file():
                    extracted_files.append(item.name)
                elif item.is_dir():
                    # If there are subdirectories, include their contents
                    for sub_item in item.rglob('*'):
                        if sub_item.is_file():
                            extracted_files.append(str(sub_item.relative_to(ZIP_DIR)))

            # Clean up the downloaded zip file
            zip_path.unlink()

            return ("Success", extracted_files)

        except (zipfile.BadZipFile, zipfile.LargeZipFile, OSError) as e:
            return (f"Error: File extraction failed - {str(e)}", [])

    except requests.RequestException as e:
        return (f"Error: Network download failed - {str(e)}", [])
    except OSError as e:
        return (f"Error: File handling failed - {str(e)}", [])
    except Exception as e:
        return (f"Error: Unexpected error - {str(e)}", [])
